    3. Initialise p avec l'adresse du premier élément du tableau.
    4. Parcourt le tableau uniquement à l'aide du pointeur.
    5. Affiche chaque mesure.
    6. Calcule la somme des mesures.
    7. Affiche la plus grande mesure.
*/

#include <stdio.h>

int main(void)
{
    // 1. Déclare le tableau.
    int mesures[8] = {12, 18, 7, 25, 14, 9, 21, 16};
    // 2. Déclare un pointeur p.
    // 3. Initialise p avec l'adresse du premier élément du tableau.
    int *p = mesures;          /* 3. p recoit l'adresse du premier element */
    int somme = 0;
    int maxi;
    int i;

    maxi = *p;                 /* on part de la premiere mesure, pas de 0 */

    // 4. Parcourt le tableau uniquement à l'aide du pointeur.
    for (i = 0; i < 8; i++) {  /* 4. on ne parcourt QU'AVEC le pointeur */
        // 5. Affiche chaque mesure.
        printf("mesure %d : %d\n", i + 1, *p);
        // 6. Calcule la somme des mesures.
        somme += *p;
        if (*p > maxi)
            maxi = *p;
        p++;
    }

    printf("somme            : %d\n", somme);
    // 7. Affiche la plus grande mesure.
    printf("plus grande      : %d\n", maxi);
    return 0;
}

