/* ========================================
 Exercice : chercher une valeur
 ========================================
On souhaite créer un programme permettant de rechercher une valeur dans une
série de données.

Le programme doit :
    1. Demander à l'utilisateur le nombre de valeurs.
    2. Réserver dynamiquement la mémoire avec malloc().
    3. Remplir la zone mémoire avec les valeurs saisies.
    4. Demander une valeur à rechercher.
    5. Parcourir les données à l'aide du pointeur.
    6. Indiquer si la valeur existe ou non.
    7. Si elle existe, afficher sa position.
    8. Libérer la mémoire avec free().
*/

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *p;
    int n, i, cherchee, position = -1;

    // 1. Demander à l'utilisateur le nombre de valeurs.
    printf("Combien de valeurs ? ");
    scanf("%d", &n);

    // 2. Réserver dynamiquement la mémoire avec malloc().
    p = malloc(n * sizeof(int));
    if (p == NULL) {
        printf("Allocation impossible\n");
        return 1;
    }

    // 3. Remplir la zone mémoire avec les valeurs saisies.
    for (i = 0; i < n; i++) {
        printf("valeur %d : ", i + 1);
        scanf("%d", &p[i]);
    }

    // 4. Demander une valeur à rechercher.
    printf("Valeur a rechercher : ");
    scanf("%d", &cherchee);

    // 5. Parcourir les données à l'aide du pointeur.
    for (i = 0; i < n; i++) {
        if (p[i] == cherchee) {
            position = i;
            break;
        }
    }

    // 6. Indiquer si la valeur existe ou non.
    // 7. Si elle existe, afficher sa position.
    if (position == -1)
        printf("%d ne figure pas dans la serie\n", cherchee);
    else
        printf("%d est a la position %d (le %d-eme)\n", cherchee, position, position + 1);

    // 8. Libérer la mémoire avec free().
    free(p);
    return 0;
}

/* ========================================
