    mini = maxi = mesures[0];               /* on part de la premiere mesure */

    printf("\nMesures enregistrees :\n");
    for (i = 0; i < n; i++) {
        printf("%.2f\n", mesures[i]);
        somme += mesures[i];
        if (mesures[i] < mini) mini = mesures[i];
        if (mesures[i] > maxi) maxi = mesures[i];
    }

    printf("moyenne  : %.2f\n", somme / n);
    printf("minimale : %.2f\n", mini);
    printf("maximale : %.2f\n", maxi);

    free(mesures);
    return 0;
}

