    // 2. Allouer dynamiquement un tableau de structures Livre.
    biblio = malloc(n * sizeof(struct Livre));
    // 3. Vérifier que l'allocation mémoire a réussi.
    if (biblio == NULL) {
        printf("Memoire insuffisante\n");
        return 1;
    }

    for (i = 0; i < n; i++) {
        // 4. Saisir les informations de chaque livre.
        printf("Livre %d — titre  : ", i + 1);  scanf("%49s", biblio[i].titre);
        printf("Livre %d — auteur : ", i + 1);  scanf("%29s", biblio[i].auteur);
        printf("Livre %d — annee  : ", i + 1);  scanf("%d", &biblio[i].annee);
        printf("Livre %d — prix   : ", i + 1);  scanf("%f", &biblio[i].prix);
    }

    // 5. Afficher les informations de tous les livres.
    printf("\n--- La bibliotheque ---\n");
    for (i = 0; i < n; i++) {
        printf("%-22s %-14s %4d  %7.2f EUR\n",
               biblio[i].titre, biblio[i].auteur, biblio[i].annee, biblio[i].prix);
        somme += biblio[i].prix;
        if (biblio[i].annee > biblio[recent].annee) recent = i;
    }

    // 6. Rechercher et afficher le livre le plus récent.
    printf("\nLe plus recent : %s (%s, %d)\n",
           biblio[recent].titre, biblio[recent].auteur, biblio[recent].annee);
    // 7. Calculer et afficher le prix moyen des livres.
    printf("Prix moyen     : %.2f EUR\n", somme / n);

    // 8. Libérer la mémoire allouée à la fin du programme.
    free(biblio);
    return 0;
}

