/* ========================================
 Exercice 1 : analyser un mot saisi
 ========================================
On souhaite écrire un programme qui analyse un mot saisi par l'utilisateur.

Écrire un programme qui :
    1. Déclare un tableau de caractères pouvant contenir un mot de 49 caractères maximum.
    2. Demande à l'utilisateur de saisir un mot.
    3. Affiche la longueur du mot à l'aide de strlen().
    4. Affiche le premier et le dernier caractère du mot.
    5. Parcourt le mot et compte le nombre de voyelles (a, e, i, o, u, y), en minuscules et en majuscules.
    6. Affiche le nombre total de voyelles.
*/

#include <stdio.h>
#include <string.h>

int main(void)
{
    // 1. Déclare un tableau de caractères pouvant contenir un mot de 49 caractères maximum.
    char mot[50];
    size_t longueur;
    size_t i;
    int voyelles = 0;

    // 2. Demande à l'utilisateur de saisir un mot.
    printf("Entrez un mot : ");
    scanf("%49s", mot);

    // 3. Affiche la longueur du mot à l'aide de strlen().
    longueur = strlen(mot);
    printf("Longueur : %zu\n", longueur);

    // 4. Affiche le premier et le dernier caractère du mot.
    printf("Premier caractere : %c\n", mot[0]);
    printf("Dernier caractere : %c\n", mot[longueur - 1]);

    // 5. Parcourt le mot et compte le nombre de voyelles (a, e, i, o, u, y),
    //    en minuscules et en majuscules.
    for (i = 0; i < longueur; i++) {
        char c = mot[i];
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'y'
         || c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y') {
            voyelles++;
        }
    }

    // 6. Affiche le nombre total de voyelles.
    printf("Nombre de voyelles : %d\n", voyelles);

    return 0;
}

/* ========================================
 Exercice 2 : comparer et copier deux noms
 ========================================
Une entreprise souhaite gérer les noms de ses techniciens.

Écrire un programme qui :
    1. Déclare deux tableaux de caractères nom1 et nom2.
    2. Demande à l'utilisateur de saisir deux noms.
    3. Affiche la longueur de chaque nom.
    4. Compare les deux noms à l'aide de strcmp().
    5. Indique si les deux noms sont identiques.
    6. Copie le premier nom dans un troisième tableau à l'aide de strcpy().
    7. Affiche le contenu du troisième tableau.
*/

#include <stdio.h>
#include <string.h>

int main(void)
{
    // 1. Déclare deux tableaux de caractères nom1 et nom2.
    char nom1[50];
    char nom2[50];
    char copie[50];

    // 2. Demande à l'utilisateur de saisir deux noms.
    printf("Premier nom  : ");
    scanf("%49s", nom1);
    printf("Deuxieme nom : ");
    scanf("%49s", nom2);

    // 3. Affiche la longueur de chaque nom.
    printf("\nLongueur de %s : %zu\n", nom1, strlen(nom1));
    printf("Longueur de %s : %zu\n", nom2, strlen(nom2));

    // 4. Compare les deux noms à l'aide de strcmp().
    // 5. Indique si les deux noms sont identiques.
    if (strcmp(nom1, nom2) == 0) {
        printf("Les deux noms sont identiques.\n");
    } else {
        printf("Les deux noms ne sont pas identiques.\n");
    }

    // 6. Copie le premier nom dans un troisième tableau à l'aide de strcpy().
