}

/* ========================================
 Exercice 3 : cinq serveurs, le plus long nom, et une recherche
 ========================================
Un service informatique souhaite enregistrer les noms de cinq serveurs.

Écrire un programme qui :
    1. Parcourt le tableau et affiche le nom de chaque serveur.
    2. Affiche la longueur du nom de chaque serveur.
    3. Détermine et affiche le nom du serveur dont le nom est le plus long.
    4. Demande à l'utilisateur de saisir le nom d'un serveur à rechercher.
    5. Parcourt le tableau pour vérifier si ce serveur existe.
    6. Affiche un message indiquant si le serveur a été trouvé ou non.
*/

#include <stdio.h>
#include <string.h>

int main(void)
{
    char serveurs[5][30] = {
        "SRV_WEB",
        "SRV_DNS",
        "SRV_BDD",
        "SRV_FICHIERS",
        "SRV_BACKUP"
    };
    char recherche[30];
    int i;
    int plus_long = 0;
    int trouve = 0;

    printf("Liste des serveurs :\n");
    for (i = 0; i < 5; i++) {
        // 1. Parcourt le tableau et affiche le nom de chaque serveur.
        // 2. Affiche la longueur du nom de chaque serveur.
        printf("  %s (%zu caracteres)\n", serveurs[i], strlen(serveurs[i]));
        // 3. Détermine le nom du serveur dont le nom est le plus long.
        if (strlen(serveurs[i]) > strlen(serveurs[plus_long])) {
            plus_long = i;
        }
    }

    // 3. ... et l'affiche.
    printf("\nNom le plus long : %s\n", serveurs[plus_long]);

    // 4. Demande à l'utilisateur de saisir le nom d'un serveur à rechercher.
    printf("\nServeur a rechercher : ");
    scanf("%29s", recherche);

    // 5. Parcourt le tableau pour vérifier si ce serveur existe.
    for (i = 0; i < 5; i++) {
        if (strcmp(serveurs[i], recherche) == 0) {
            trouve = 1;
        }
    }

    // 6. Affiche un message indiquant si le serveur a été trouvé ou non.
    if (trouve) {
        printf("Le serveur %s existe.\n", recherche);
    } else {
        printf("Le serveur %s est introuvable.\n", recherche);
    }

    return 0;
}

