#include <iostream>
#include <string>
#include <vector>

class Compte {
    std::string titulaire;
    double solde;

public:
    Compte(std::string t, double depart) : titulaire(t), solde(depart) {}

    void deposer(double montant) { solde += montant; }

    bool retirer(double montant) {
        if (montant > solde) return false;
        solde -= montant;
        return true;
    }

    void afficher() const {
        std::cout << titulaire << " : " << solde << " euros" << std::endl;
    }
};

int main()
{
    std::vector<Compte> comptes;
    comptes.push_back(Compte("Aya", 120.0));
    comptes.push_back(Compte("Karim", 80.0));

    comptes[0].deposer(30.5);
    if (!comptes[1].retirer(200)) {
        std::cout << "Retrait refuse : solde insuffisant." << std::endl;
    }

    for (const Compte& c : comptes) c.afficher();
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>

struct Mesure { std::string machine; int ping; };

int main()
{
    std::vector<Mesure> m = {{"srv-web", 48}, {"srv-bdd", 12}, {"poste-12", 97}};

    std::sort(m.begin(), m.end(),
              [](const Mesure& a, const Mesure& b) { return a.ping < b.ping; });

    for (const Mesure& x : m) {
        std::cout << x.machine << " -> " << x.ping << " ms" << std::endl;
    }

    std::map<std::string, int> total;
    for (const Mesure& x : m) total[x.ping < 50 ? "rapide" : "lent"]++;

    for (const auto& paire : total) {
        std::cout << paire.first << " : " << paire.second << std::endl;
    }
    return 0;
}
